// Package golang holds the generated Go clients for the services in this
// repository: one package per <service>.json.
//
// The files are generated by xbot-codegen (xbot_framework) and checked in. Do not
// edit them by hand; after changing a schema run:
//
// go generate ./...
//
// CI should run `go generate ./... && git diff --exit-code` so a schema change
// without a regenerated client fails the build.
package golang

